-- Colorscheme built from the palette generated by matugen.
--
-- matugen writes ~/.cache/matugen/nvim-colors.lua from the template in
-- ~/.config/matugen/templates/nvim-colors.lua every time the wallpaper
-- changes. A filesystem watcher re-applies the highlights when that happens,
-- so Neovim follows the desktop without a restart.
--
-- Adapted from caelestia-dots/caelestia nvim/colors/caelestia.lua.
--
--   :colorscheme wallpaper
--   vim.g.wallpaper_transparent = false  -- solid surfaces instead of NONE

local uv = vim.uv or vim.loop

local palette_path = vim.fn.expand '~/.cache/matugen/nvim-colors.lua'
local cache_dir = vim.fn.fnamemodify(palette_path, ':h')

-- Roles this file reads. If any is missing the scheme is left untouched
-- rather than half applied.
local required = {
  'surface',
  'surface_container',
  'surface_container_low',
  'surface_container_high',
  'surface_container_highest',
  'on_surface',
  'on_surface_variant',
  'outline',
  'outline_variant',
  'primary',
  'on_primary',
  'primary_container',
  'on_primary_container',
  'secondary',
  'tertiary',
  'on_tertiary',
  'tertiary_container',
  'on_tertiary_container',
  'error',
}

-- The matugen template uses shorter names than the highlight groups below and
-- does not emit the on_tertiary* roles. Map what exists and derive the rest
-- from the Material roles so `apply()` stays unchanged.
local function read_palette()
  local chunk = loadfile(palette_path)
  if not chunk then return nil end

  local ok, t = pcall(chunk)
  if not ok or type(t) ~= 'table' then return nil end

  local p = {
    surface = t.surface,
    surface_container = t.surface_container,
    surface_container_low = t.surface_low,
    surface_container_high = t.surface_high,
    surface_container_highest = t.surface_highest,
    on_surface = t.on_surface,
    on_surface_variant = t.on_surface_variant,
    outline = t.outline,
    outline_variant = t.outline_variant,
    primary = t.primary,
    on_primary = t.on_primary,
    primary_container = t.primary_container,
    on_primary_container = t.on_primary_container,
    secondary = t.secondary,
    secondary_container = t.secondary_container,
    on_secondary_container = t.on_secondary_container,
    tertiary = t.tertiary,
    tertiary_container = t.tertiary_container,
    error = t.error,
    error_container = t.error_container,
  }

  p.on_tertiary = p.on_primary
  p.on_tertiary_container = p.on_primary_container

  for _, k in ipairs(required) do
    if not p[k] then return nil end
  end
  return p
end

local function hex_to_rgb(hex)
  return tonumber(hex:sub(2, 3), 16), tonumber(hex:sub(4, 5), 16), tonumber(hex:sub(6, 7), 16)
end

local function rgb_to_hex(r, g, b)
  return string.format('#%02x%02x%02x', math.floor(r + 0.5), math.floor(g + 0.5), math.floor(b + 0.5))
end

local function blend(c1, c2, a)
  local r1, g1, b1 = hex_to_rgb(c1)
  local r2, g2, b2 = hex_to_rgb(c2)
  return rgb_to_hex(r1 * a + r2 * (1 - a), g1 * a + g2 * (1 - a), b1 * a + b2 * (1 - a))
end

local function apply(p)
  -- Clear first, else groups set below leak in from the previous colorscheme.
  -- background before colors_name: nvim re-sources the colorscheme on change.
  vim.cmd 'highlight clear'
  if vim.fn.exists 'syntax_on' == 1 then vim.cmd 'syntax reset' end
  vim.o.background = 'dark'
  vim.g.colors_name = 'wallpaper'

  local transparent = vim.g.wallpaper_transparent ~= false
  local bg = transparent and 'NONE' or p.surface
  local container_bg = transparent and 'NONE' or p.surface_container
  local container_low_bg = transparent and 'NONE' or p.surface_container_low
  local hl = function(g, s) vim.api.nvim_set_hl(0, g, s) end

  -- Editor UI
  hl('Normal', { fg = p.on_surface, bg = bg })
  hl('NormalNC', { fg = p.on_surface, bg = bg })
  hl('NormalFloat', { fg = p.on_surface, bg = container_bg })
  hl('FloatBorder', { fg = p.outline, bg = 'NONE' })
  hl('FloatTitle', { fg = p.primary, bold = true })
  hl('CursorLine', { bg = p.surface_container_high })
  hl('CursorLineNr', { fg = p.primary, bold = true })
  hl('LineNr', { fg = p.outline })
  hl('SignColumn', { bg = bg })
  hl('WinSeparator', { fg = p.outline_variant })
  hl('VertSplit', { fg = p.outline_variant })
  hl('MatchParen', { fg = p.primary, bold = true, underline = true })
  hl('NonText', { fg = p.outline })
  hl('Whitespace', { fg = p.outline_variant })
  hl('ColorColumn', { bg = p.surface_container })
  hl('Folded', { fg = p.on_surface_variant, bg = p.surface_container })
  hl('Conceal', { fg = p.on_surface_variant })
  hl('Cursor', { fg = p.on_primary, bg = p.primary })

  -- Selection / search
  hl('Visual', { fg = p.on_primary_container, bg = p.primary_container })
  hl('VisualNOS', { fg = p.on_primary_container, bg = p.primary_container })
  hl('Search', { fg = p.on_tertiary_container, bg = p.tertiary_container })
  hl('IncSearch', { fg = p.on_primary, bg = p.primary })
  hl('CurSearch', { fg = p.on_primary, bg = p.primary })

  -- Completion menu
  hl('Pmenu', { fg = p.on_surface, bg = p.surface_container_high })
  hl('PmenuSel', { fg = p.on_primary_container, bg = p.primary_container, bold = true })
  hl('PmenuSbar', { bg = p.surface_container_highest })
  hl('PmenuThumb', { bg = p.outline })

  -- Statusline / tabline
  hl('StatusLine', { fg = p.on_surface, bg = container_bg })
  hl('StatusLineNC', { fg = p.on_surface_variant, bg = container_low_bg })
  hl('TabLineSel', { fg = p.primary, bg = bg, bold = true })
  hl('WinBar', { fg = p.on_surface_variant, bg = bg })

  -- Spell
  hl('SpellBad', { sp = p.error, undercurl = true })
  hl('SpellCap', { sp = p.tertiary, undercurl = true })
  hl('SpellRare', { sp = p.tertiary, undercurl = true })
  hl('SpellLocal', { sp = p.secondary, undercurl = true })

  -- Diff (blended so it sits subtly over the surface)
  hl('DiffAdd', { bg = blend(p.secondary, p.surface, 0.25) })
  hl('DiffChange', { bg = blend(p.tertiary, p.surface, 0.20) })
  hl('DiffDelete', { bg = blend(p.error, p.surface, 0.25) })
  hl('DiffText', { bg = blend(p.tertiary, p.surface, 0.45) })

  -- Syntax
  hl('Comment', { fg = p.on_surface_variant, italic = true })
  hl('String', { fg = p.secondary })
  hl('Number', { fg = p.tertiary })
  hl('Boolean', { fg = p.tertiary })
  hl('Constant', { fg = p.tertiary })
  hl('Function', { fg = p.primary })
  hl('Statement', { fg = p.tertiary })
  hl('Operator', { fg = p.secondary })
  hl('Type', { fg = p.tertiary })
  hl('PreProc', { fg = p.error })
  hl('Special', { fg = p.secondary })
  hl('Delimiter', { fg = p.on_surface_variant })
  hl('Error', { fg = p.error })
  hl('Todo', { fg = p.on_tertiary, bg = p.tertiary, bold = true })
  hl('Title', { fg = p.primary, bold = true })
  hl('Identifier', { fg = p.on_surface })

  -- Treesitter
  hl('@variable', { fg = p.on_surface })
  hl('@variable.builtin', { fg = p.tertiary })
  hl('@variable.parameter', { fg = p.on_surface })
  hl('@variable.member', { fg = p.on_surface })
  hl('@property', { fg = p.on_surface })
  hl('@function', { fg = p.primary })
  hl('@function.builtin', { fg = p.tertiary })
  hl('@function.macro', { fg = p.error })
  hl('@constructor', { fg = p.tertiary })
  hl('@keyword', { fg = p.tertiary })
  hl('@keyword.return', { fg = p.tertiary, bold = true })
  hl('@string.escape', { fg = p.secondary })
  hl('@type.builtin', { fg = p.tertiary, italic = true })
  hl('@tag', { fg = p.primary })
  hl('@tag.attribute', { fg = p.on_surface })
  hl('@namespace', { fg = p.tertiary })
  hl('@punctuation.bracket', { fg = p.on_surface_variant })
  hl('@markup.heading', { fg = p.primary, bold = true })
  hl('@markup.link', { fg = p.primary, underline = true })
  hl('@diff.plus', { fg = p.secondary })
  hl('@diff.minus', { fg = p.error })

  -- LSP semantic tokens
  hl('@lsp.type.namespace', { link = '@namespace' })
  hl('@lsp.type.type', { link = '@type' })
  hl('@lsp.type.class', { link = '@type' })
  hl('@lsp.type.parameter', { link = '@variable.parameter' })
  hl('@lsp.type.property', { link = '@property' })
  hl('@lsp.type.enumMember', { link = '@number' })
  hl('@lsp.type.function', { link = '@function' })
  hl('@lsp.type.method', { link = '@function' })
  hl('@lsp.type.macro', { link = '@function.macro' })
  hl('@lsp.typemod.variable.readonly', { fg = p.tertiary })

  -- LSP references
  hl('LspReferenceText', { bg = p.surface_container_high })
  hl('LspReferenceRead', { bg = p.surface_container_high })
  hl('LspReferenceWrite', { bg = p.surface_container_high })

  -- Diagnostics
  hl('DiagnosticError', { fg = p.error })
  hl('DiagnosticWarn', { fg = p.tertiary })
  hl('DiagnosticInfo', { fg = p.primary })
  hl('DiagnosticHint', { fg = p.secondary })
  hl('DiagnosticOk', { fg = p.secondary })
  hl('DiagnosticUnderlineError', { sp = p.error, undercurl = true })
  hl('DiagnosticUnderlineWarn', { sp = p.tertiary, undercurl = true })
  hl('DiagnosticUnderlineInfo', { sp = p.primary, undercurl = true })
  hl('DiagnosticUnderlineHint', { sp = p.secondary, undercurl = true })
  hl('DiagnosticUnderlineOk', { sp = p.secondary, undercurl = true })
  hl('DiagnosticVirtualTextError', { fg = p.error, bg = blend(p.error, p.surface, 0.15) })
  hl('DiagnosticVirtualTextWarn', { fg = p.tertiary, bg = blend(p.tertiary, p.surface, 0.15) })
  hl('DiagnosticVirtualTextInfo', { fg = p.primary, bg = blend(p.primary, p.surface, 0.15) })
  hl('DiagnosticVirtualTextHint', { fg = p.secondary, bg = blend(p.secondary, p.surface, 0.15) })
  hl('DiagnosticVirtualTextOk', { fg = p.secondary, bg = blend(p.secondary, p.surface, 0.15) })

  -- Floats that should sit on the panel colour
  for _, g in ipairs {
    'TelescopeNormal',
    'TelescopePromptNormal',
    'TelescopeResultsNormal',
    'TelescopePreviewNormal',
    'LazyNormal',
    'MasonNormal',
    'WhichKeyFloat',
    'WhichKeyNormal',
  } do
    hl(g, { bg = container_bg })
  end

  for _, g in ipairs {
    'TelescopeBorder',
    'TelescopePromptBorder',
    'TelescopeResultsBorder',
    'TelescopePreviewBorder',
    'WhichKeyBorder',
  } do
    hl(g, { fg = p.outline, bg = 'NONE' })
  end

  hl('TelescopeSelection', { bg = p.surface_container_high, bold = true })
  hl('TelescopeMatching', { fg = p.primary, bold = true })
  hl('TelescopePromptPrefix', { fg = p.primary })

  -- Directory is used by nvim-tree, oil, fzf-lua and the completion menus
  hl('Directory', { fg = p.primary })

  -- nvim-tree
  hl('NvimTreeNormal', { fg = p.on_surface, bg = container_bg })
  hl('NvimTreeNormalNC', { bg = container_bg })
  hl('NvimTreeWinSeparator', { fg = p.outline_variant, bg = container_bg })
  hl('NvimTreeRootFolder', { fg = p.primary, bold = true })
  hl('NvimTreeFolderIcon', { fg = p.primary })
  hl('NvimTreeFolderName', { fg = p.on_surface })
  hl('NvimTreeOpenedFolderName', { fg = p.primary, bold = true })
  hl('NvimTreeEmptyFolderName', { fg = p.outline })
  hl('NvimTreeOpenedFile', { fg = p.primary })
  hl('NvimTreeSpecialFile', { fg = p.tertiary, underline = true })
  hl('NvimTreeIndentMarker', { fg = p.outline_variant })
  hl('NvimTreeCursorLine', { bg = p.surface_container_high })
  hl('NvimTreeGitDirty', { fg = p.tertiary })
  hl('NvimTreeGitNew', { fg = p.secondary })
  hl('NvimTreeGitDeleted', { fg = p.error })
  hl('NvimTreeGitStaged', { fg = p.secondary })
  hl('NvimTreeGitMerge', { fg = p.error })

  -- bufferline
  --
  -- Every group needs an explicit background. bufferline's own defaults only
  -- set a foreground, so any segment it draws (numbers, the close button,
  -- duplicate markers, diagnostic counts, ...) would be transparent and punch
  -- a hole in the selected tab's pill. The `*Selected` variants all share
  -- `sel_bg` so the active tab reads as one solid shape.
  local sel_bg = p.surface_container_high
  local sel_fg = p.primary

  hl('BufferLineFill', { bg = container_bg })
  hl('BufferLineBackground', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineBuffer', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineBufferVisible', { fg = p.on_surface, bg = container_bg })
  hl('BufferLineBufferSelected', { fg = sel_fg, bg = sel_bg, bold = true })
  hl('BufferLineIndicatorSelected', { fg = sel_fg, bg = sel_bg })
  hl('BufferLineIndicatorVisible', { fg = p.outline_variant, bg = container_bg })
  hl('BufferLineSeparator', { fg = p.outline_variant, bg = container_bg })
  hl('BufferLineSeparatorSelected', { fg = p.outline_variant, bg = sel_bg })
  hl('BufferLineOffsetSeparator', { fg = p.outline_variant, bg = container_bg })
  hl('BufferLineTruncMarker', { fg = p.outline, bg = container_bg })
  hl('BufferLineModified', { fg = p.tertiary, bg = container_bg })
  hl('BufferLineModifiedVisible', { fg = p.tertiary, bg = container_bg })
  hl('BufferLineModifiedSelected', { fg = p.tertiary, bg = sel_bg })
  hl('BufferLineCloseButton', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineCloseButtonVisible', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineCloseButtonSelected', { fg = p.error, bg = sel_bg })
  hl('BufferLineDuplicate', { fg = p.outline, bg = container_bg, italic = true })
  hl('BufferLineDuplicateVisible', { fg = p.outline, bg = container_bg, italic = true })
  hl('BufferLineDuplicateSelected', { fg = p.outline, bg = sel_bg, italic = true })
  hl('BufferLineNumbers', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineNumbersVisible', { fg = p.on_surface, bg = container_bg })
  hl('BufferLineNumbersSelected', { fg = sel_fg, bg = sel_bg, bold = true })
  hl('BufferLinePick', { fg = p.on_primary, bg = p.primary, bold = true })
  hl('BufferLinePickVisible', { fg = p.on_primary, bg = p.primary, bold = true })
  hl('BufferLinePickSelected', { fg = p.on_primary, bg = p.primary, bold = true })
  hl('BufferLineGroupLabel', { fg = p.on_primary, bg = p.primary })
  hl('BufferLineGroupSeparator', { fg = p.outline_variant, bg = container_bg })
  hl('BufferLineDiagnostic', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineDiagnosticVisible', { fg = p.on_surface, bg = container_bg })
  hl('BufferLineDiagnosticSelected', { fg = p.error, bg = sel_bg, bold = true })

  -- Tab mode (bufferline's `mode = "tabs"`), in case it is switched later.
  hl('BufferLineTab', { fg = p.on_surface_variant, bg = container_bg })
  hl('BufferLineTabSelected', { fg = sel_fg, bg = sel_bg, bold = true })
  hl('BufferLineTabSeparator', { fg = p.outline_variant, bg = container_bg })
  hl('BufferLineTabSeparatorSelected', { fg = p.outline_variant, bg = sel_bg })
  hl('BufferLineTabClose', { fg = p.error, bg = container_bg })

  -- Diagnostic variants: coloured foreground, background follows the tab.
  for _, d in ipairs {
    { 'Error', p.error },
    { 'Warning', p.tertiary },
    { 'Info', p.primary },
    { 'Hint', p.secondary },
  } do
    local name, colour = d[1], d[2]
    hl('BufferLine' .. name, { fg = colour, bg = container_bg })
    hl('BufferLine' .. name .. 'Visible', { fg = colour, bg = container_bg })
    hl('BufferLine' .. name .. 'Selected', { fg = colour, bg = sel_bg })
    hl('BufferLine' .. name .. 'Diagnostic', { fg = colour, bg = container_bg })
    hl('BufferLine' .. name .. 'DiagnosticVisible', { fg = colour, bg = container_bg })
    hl('BufferLine' .. name .. 'DiagnosticSelected', { fg = colour, bg = sel_bg })
  end

  -- nvim-cmp
  hl('CmpItemAbbr', { fg = p.on_surface })
  hl('CmpItemAbbrDeprecated', { fg = p.outline, strikethrough = true })
  hl('CmpItemAbbrMatch', { fg = p.primary, bold = true })
  hl('CmpItemAbbrMatchFuzzy', { fg = p.primary, bold = true })
  hl('CmpItemKind', { fg = p.secondary or p.primary })
  hl('CmpItemMenu', { fg = p.outline, italic = true })

  -- gitsigns
  hl('GitSignsAdd', { fg = p.secondary })
  hl('GitSignsChange', { fg = p.tertiary })
  hl('GitSignsDelete', { fg = p.error })
  hl('GitSignsAddInline', { bg = blend(p.secondary, p.surface, 0.25) })
  hl('GitSignsChangeInline', { bg = blend(p.tertiary, p.surface, 0.25) })
  hl('GitSignsDeleteInline', { bg = blend(p.error, p.surface, 0.25) })

  -- flash.nvim
  hl('FlashLabel', { fg = p.on_primary, bg = p.primary, bold = true })
  hl('FlashMatch', { fg = p.on_surface, bg = p.surface_container_highest })
  hl('FlashCurrent', { fg = p.on_primary_container, bg = p.primary_container })
  hl('FlashBackdrop', { fg = p.outline })

  -- alpha dashboard
  hl('DashboardHeader', { fg = p.primary })
  hl('DashboardCenter', { fg = p.on_surface_variant })
  hl('DashboardShortCut', { fg = p.primary })
  hl('DashboardFooter', { fg = p.outline, italic = true })

  -- mini.icons sets these with default = true on ColorScheme, which usually
  -- fires before it lazy loads, so set them here instead
  hl('MiniIconsAzure', { fg = p.primary })
  hl('MiniIconsBlue', { fg = p.primary })
  hl('MiniIconsCyan', { fg = p.secondary })
  hl('MiniIconsGreen', { fg = p.secondary })
  hl('MiniIconsGrey', { fg = p.on_surface_variant })
  hl('MiniIconsOrange', { fg = p.error })
  hl('MiniIconsPurple', { fg = p.tertiary })
  hl('MiniIconsRed', { fg = p.error })
  hl('MiniIconsYellow', { fg = p.tertiary })
end

-- Watch the directory, not the file: matugen writes nvim-colors.lua by
-- truncating and rewriting it, and the file may not exist yet on a fresh
-- install.
--
-- Apply immediately on an event, then once more after 250ms. The second pass
-- catches partial reads and plugins whose ColorScheme handlers run after ours
-- and re-set from defaults.

local verify_timer

local function read_apply()
  -- Nothing tears the watcher down, so bail if the user switched away
  if vim.g.colors_name ~= 'wallpaper' then return true end
  local p = read_palette()
  if not p then return false end -- partial / corrupt; the verify pass retries
  apply(p)
  pcall(vim.api.nvim_exec_autocmds, 'ColorScheme', { pattern = 'wallpaper', modeline = false })
  return true
end

local function trigger()
  pcall(read_apply) -- immediate; may no-op if the file is mid-write
  if verify_timer and not verify_timer:is_closing() then
    verify_timer:stop()
    verify_timer:close()
  end
  -- Local, not the upvalue: the callback must close its own timer, which may
  -- not be the current one by the time it runs
  local timer = uv.new_timer()
  verify_timer = timer
  timer:start(
    250,
    0,
    vim.schedule_wrap(function()
      if not timer:is_closing() then timer:close() end
      if verify_timer == timer then verify_timer = nil end
      pcall(read_apply)
    end)
  )
end

local function watch()
  -- Guard lives outside the chunk: nvim re-sources this file on every
  -- :colorscheme wallpaper, leaking a handle each time otherwise
  if vim.g.wallpaper_watching then return end
  local handle = uv.new_fs_event()
  if not handle then return end
  local ok = handle:start(
    cache_dir,
    {},
    vim.schedule_wrap(function(err, filename)
      if err then return end
      if filename == nil or filename == 'nvim-colors.lua' then trigger() end
    end)
  )
  if not ok then
    handle:close()
    return
  end
  vim.g.wallpaper_watching = true
end

local p = read_palette()
if p then
  apply(p)
else
  -- No usable palette yet; claim the name anyway so the watcher can fill in
  vim.cmd 'highlight clear'
  if vim.fn.exists 'syntax_on' == 1 then vim.cmd 'syntax reset' end
  vim.g.colors_name = 'wallpaper'
end
watch()
